questions.modelAnswer:
class Reg32 {
  volatile uint32_t* const p_;
public:
  explicit Reg32(uintptr_t addr)
      : p_(reinterpret_cast<volatile uint32_t*>(addr)) {}
  uint32_t read() const { return *p_; }        // one 32-bit load
  void write(uint32_t v) { *p_ = v; }           // one 32-bit store
  // Read-modify-write: NOT atomic. Do not use on W1C or read-to-clear
  // registers, and protect it if an ISR touches the same register.
  void modify(uint32_t mask, uint32_t value) {
    uint32_t v = *p_;
    v = (v & ~mask) | (value & mask);
    *p_ = v;
  }
};
